// JARVIS is the single authoritative voice/text pipeline. Realtime uses WebRTC;
// browser recognition and speech synthesis are compatibility fallbacks only.
const JARVIS_SESSION_KEY='foundly_jarvis_conversation_v1';
function storedConversation(){try{const row=JSON.parse(sessionStorage.getItem(JARVIS_SESSION_KEY)||'null');return row&&/^[A-Za-z0-9_-]{16,160}$/.test(row.id)&&Number(row.expires_at)>Date.now()?row.id:null}catch{return null}}
const JARVIS={enabled:false,conversationActive:false,conversationId:storedConversation(),state:'STANDBY',wakeRecognition:null,wakeRunning:false,localWake:false,fallback:false,fallbackSpeaking:false,pc:null,dc:null,micStream:null,audio:null,realtimeConnected:false,connecting:null,handledCalls:new Set(),lastTranscript:null,lastConfirmation:null,location:null,timeoutMs:90000,idleTimer:null,reconnects:0,reconnectTimer:null,manualClose:false};
function randomId(){return globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}
function cleanSpeech(s){return String(s||'').toLowerCase().replace(/[,.!?;:]+/g,' ').replace(/\s+/g,' ').trim()}
function stripJarvisWake(s){const raw=cleanSpeech(s),m=raw.match(/^(?:hey\s+)?jarvis\b\s*(.*)$/i);return m?m[1].trim():null}
function setJarvisState(state,detail=''){JARVIS.state=state;const el=$('#voiceState'),bar=document.querySelector('.voicebar'),mic=$('#mic');if(el)el.textContent=state;if(bar)bar.dataset.state=state;if(mic){mic.classList.toggle('listening',['WAKE','LISTENING'].includes(state));mic.classList.toggle('thinking',['UNDERSTANDING','SEARCHING','THINKING','EXECUTING','VERIFYING'].includes(state));mic.setAttribute('aria-pressed',String(JARVIS.enabled))}if(detail&&$('#listenText'))$('#listenText').textContent=detail}
function rememberConversation(){if(JARVIS.conversationId)try{sessionStorage.setItem(JARVIS_SESSION_KEY,JSON.stringify({id:JARVIS.conversationId,expires_at:Date.now()+JARVIS.timeoutMs}))}catch{}}
function resetConversationTimer(){clearTimeout(JARVIS.idleTimer);if(!JARVIS.conversationActive)return;rememberConversation();JARVIS.idleTimer=setTimeout(()=>endJarvisConversation(true),JARVIS.timeoutMs)}
function conversationId(){if(!JARVIS.conversationId)JARVIS.conversationId=randomId();rememberConversation();return JARVIS.conversationId}
async function getGrantedLocation(){if(!navigator.geolocation)return null;try{if(navigator.permissions){const p=await navigator.permissions.query({name:'geolocation'});if(p.state!=='granted')return null}return await new Promise(resolve=>navigator.geolocation.getCurrentPosition(x=>resolve({latitude:x.coords.latitude,longitude:x.coords.longitude,accuracy:x.coords.accuracy}),()=>resolve(null),{enableHighAccuracy:false,timeout:3000,maximumAge:300000}))}catch{return null}}
function stopWakeListener(){JARVIS.wakeRunning=false;try{JARVIS.wakeRecognition?.stop()}catch{}}
function initWakeListener(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return null;const rec=new SR();rec.lang='nl-NL';rec.continuous=true;rec.interimResults=false;rec.maxAlternatives=1;if('processLocally'in rec){try{rec.processLocally=true;JARVIS.localWake=true}catch{JARVIS.localWake=false}}rec.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)handleWakeTranscript(e.results[i][0].transcript)};rec.onend=()=>{JARVIS.wakeRunning=false;if(JARVIS.enabled&&JARVIS.localWake&&!JARVIS.realtimeConnected&&!JARVIS.fallbackSpeaking)setTimeout(startWakeListener,350)};rec.onerror=e=>{JARVIS.wakeRunning=false;if(e.error==='not-allowed'||e.error==='service-not-allowed'){JARVIS.enabled=false;setJarvisState('ERROR','Microfoontoegang is geweigerd.')}else if(['language-not-supported','network'].includes(e.error)){JARVIS.localWake=false;setJarvisState('STANDBY','Lokale wake-word niet beschikbaar · klik om een gesprek te starten of gebruik tekst')}else if(JARVIS.enabled&&JARVIS.localWake&&!JARVIS.realtimeConnected&&!JARVIS.fallbackSpeaking)setTimeout(startWakeListener,1000)};JARVIS.wakeRecognition=rec;return rec}
function startWakeListener(){if(!JARVIS.enabled||JARVIS.realtimeConnected||JARVIS.fallbackSpeaking||JARVIS.wakeRunning)return;const rec=JARVIS.wakeRecognition||initWakeListener();if(!rec||!JARVIS.localWake){setJarvisState('STANDBY','Geen lokale wake-word capability · klik om een gesprek te starten of gebruik tekst');return}try{rec.start();JARVIS.wakeRunning=true;setJarvisState(JARVIS.conversationActive?'LISTENING':'STANDBY',JARVIS.conversationActive?'Lokale conversation fallback luistert':`MIC ACTIVE · zeg “Jarvis” · lokale herkenning`)}catch{}}
async function activateJarvis(){if(JARVIS.enabled){if(!JARVIS.localWake&&!JARVIS.conversationActive){JARVIS.conversationActive=true;JARVIS.conversationId=randomId();rememberConversation();setJarvisState('WAKE','Jarvis is wakker');await wakeJarvis();return}deactivateJarvis();return}if(!isSecureContext||!navigator.mediaDevices?.getUserMedia){setJarvisState('ERROR','Jarvis vereist HTTPS en microfoontoegang.');return}try{setJarvisState('WAKE','Microfoontoegang aanvragen…');const permissionStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});permissionStream.getTracks().forEach(t=>t.stop());JARVIS.enabled=true;JARVIS.location=await getGrantedLocation();initWakeListener();startWakeListener()}catch(e){setJarvisState('ERROR',`Microfoon niet beschikbaar: ${e.message}`)}}
