async function handleWakeTranscript(transcript){const wakeRest=stripJarvisWake(transcript);if(!JARVIS.conversationActive&&wakeRest===null)return;if(!JARVIS.conversationActive){JARVIS.conversationActive=true;JARVIS.conversationId=randomId();rememberConversation();setJarvisState('WAKE','Jarvis is wakker');stopWakeListener();await wakeJarvis(wakeRest);return}if(JARVIS.fallback&&!JARVIS.fallbackSpeaking){const text=wakeRest===null?cleanSpeech(transcript):wakeRest;if(text)await route(text,true)}}
async function wakeJarvis(initialText=''){try{await connectRealtime();JARVIS.fallback=false;resetConversationTimer();if(initialText)await route(initialText,true);else requestRealtimeSpeech('Ja.')}catch(e){JARVIS.fallback=true;setJarvisState('LISTENING',`Realtime niet beschikbaar · veilige fallback: ${e.message}`);if(initialText)await route(initialText,true);else fallbackSpeak('Ja.');startWakeListener()}}
function closeRealtime(manual=false){JARVIS.manualClose=manual;JARVIS.realtimeConnected=false;if(manual){clearTimeout(JARVIS.reconnectTimer);JARVIS.reconnectTimer=null}const dc=JARVIS.dc,pc=JARVIS.pc;try{if(dc){dc.onopen=null;dc.onmessage=null;dc.onerror=null;dc.onclose=null;dc.close()}}catch{}try{if(pc){pc.ontrack=null;pc.onconnectionstatechange=null;pc.close()}}catch{}try{JARVIS.micStream?.getTracks().forEach(t=>t.stop())}catch{}if(JARVIS.audio){JARVIS.audio.pause();JARVIS.audio.srcObject=null}JARVIS.dc=null;JARVIS.pc=null;JARVIS.micStream=null;JARVIS.audio=null}
