function scheduleRealtimeReconnect(){if(JARVIS.reconnectTimer||JARVIS.connecting)return;if(JARVIS.reconnects>=3){JARVIS.fallback=true;closeRealtime(false);setJarvisState('LISTENING','Realtime verbroken · conversation fallback actief');return startWakeListener()}const delay=500*(2**JARVIS.reconnects++);setJarvisState('THINKING',`Realtime herstellen · poging ${JARVIS.reconnects}/3`);JARVIS.reconnectTimer=setTimeout(()=>{JARVIS.reconnectTimer=null;connectRealtime().catch(()=>scheduleRealtimeReconnect())},delay)}
function realtimeSend(event){if(JARVIS.dc?.readyState!=='open')return false;JARVIS.dc.send(JSON.stringify(event));return true}
function requestRealtimeSpeech(answer,voiceMode='CONVERSATION'){if(!answer||!JARVIS.realtimeConnected)return false;setJarvisState('SPEAKING',`Jarvis antwoordt · ${voiceMode}`);return realtimeSend({type:'response.create',response:{output_modalities:['audio'],tool_choice:'none',instructions:`Modus ${String(voiceMode).slice(0,40)}. Spreek in natuurlijk Nederlands uitsluitend dit geverifieerde Foundly-resultaat uit. Houd het compact en voeg niets toe:\n${String(answer).slice(0,6000)}`}})}
function currentTranscript(fallback){const t=JARVIS.lastTranscript;if(t&&Date.now()-t.at<20000)return t.text;return fallback}
function isConfirmation(s){return /^(ja[,. ]*)?(bevestig|doe maar|akkoord|voer uit|yes|confirm)( dit)?[.! ]*$/i.test(String(s||'').trim())}
async function handleRealtimeToolCall(event){const callId=event.call_id||event.item?.call_id;if(!callId||JARVIS.handledCalls.has(callId))return;JARVIS.handledCalls.add(callId);if(JARVIS.handledCalls.size>300)JARVIS.handledCalls=new Set([...JARVIS.handledCalls].slice(-150));let args={};try{args=JSON.parse(event.arguments||event.item?.arguments||'{}')}catch{}const message=currentTranscript(args.message||'');if(!message){return realtimeSend({type:'conversation.item.create',item:{type:'function_call_output',call_id:callId,output:JSON.stringify({ok:false,error:'Geen transcript beschikbaar'})}})}setJarvisState('EXECUTING','Foundly Core voert de opdracht uit…');let result;try{result=await executeJarvisTurn(message,{turn_id:callId})}catch(e){result={ok:false,status:'error',answer:`De opdracht is niet uitgevoerd: ${e.message}`,ui_commands:[]}}const voiceResult={ok:result.ok,status:result.status,answer:result.answer,voice_mode:result.voice_mode,actions:(result.actions||[]).map(x=>({type:x.type,status:x.status,reason:x.reason})),verification:result.verification,ui_commands:result.ui_commands};realtimeSend({type:'conversation.item.create',item:{type:'function_call_output',call_id:callId,output:JSON.stringify(voiceResult)}});realtimeSend({type:'response.create',response:{output_modalities:['audio'],tool_choice:'none',instructions:`Modus ${String(result.voice_mode||'CONVERSATION').slice(0,40)}. Spreek het foundly_core-resultaat kort en exact uit. Verzin niets en beweer geen actie die niet als uitgevoerd is gemarkeerd.`}});resetConversationTimer()}
function handleRealtimeEvent(event){if(event.type==='conversation.item.input_audio_transcription.completed'&&event.transcript){JARVIS.lastTranscript={text:event.transcript,at:Date.now()};$('#listenText').textContent=`Gehoord: ${event.transcript}`;resetConversationTimer()}if(event.type==='input_audio_buffer.speech_started'){if(JARVIS.state==='SPEAKING')realtimeSend({type:'response.cancel'});JARVIS.lastTranscript=null;setJarvisState('LISTENING','Luisteren…');resetConversationTimer()}if(event.type==='input_audio_buffer.speech_stopped')setJarvisState('UNDERSTANDING','Opdracht begrijpen…');if(event.type==='response.created')setJarvisState('THINKING','Nadenken…');if(event.type==='response.output_audio.delta'||event.type==='response.audio.delta')setJarvisState('SPEAKING','Jarvis antwoordt');if(event.type==='response.function_call_arguments.done')handleRealtimeToolCall(event);if(event.type==='response.output_item.done'&&event.item?.type==='function_call')handleRealtimeToolCall(event);if(event.type==='response.done'){setJarvisState('DONE','Gereed · conversation mode blijft actief');setTimeout(()=>{if(JARVIS.conversationActive)setJarvisState('LISTENING','CONVERSATION MODE · spreek verder')},700);resetConversationTimer()}if(event.type==='error')setJarvisState('ERROR',`Realtime fout: ${event.error?.message||'onbekend'}`)}
async function executeJarvisTurn(message,options={}){const payload={message:String(message).trim(),conversation_id:conversationId(),turn_id:options.turn_id||randomId(),preferred_module:options.preferred_module||null,client_context:{timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,location:JARVIS.location}};if(JARVIS.lastConfirmation&&isConfirmation(message))payload.confirmation_id=JARVIS.lastConfirmation.id;setJarvisState(/\b(zoek|weer|nieuws|actueel|online)\b/i.test(message)?'SEARCHING':'UNDERSTANDING','Jarvis verwerkt de opdracht…');const r=await fetch('/api/jarvis/turn',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),j=await r.json();if(!r.ok)throw new Error(j.error||'Jarvis-opdracht mislukt');JARVIS.lastConfirmation=j.confirmation||null;const commands=j.ui_commands||[];await UICommandBus.apply(commands,j);const displayed=commands.some(x=>['SHOW_RESULTS','SHOW_REPORT','SHOW_TASK','SHOW_VEHICLE'].includes(x.type)),navigationOnly=j.intent==='ui_navigation'&&commands.length>0;if(!displayed&&!navigationOnly)showJarvisResult(j);resetConversationTimer();return j}
function fallbackVoice(){const voices=speechSynthesis?.getVoices?.()||[],nl=voices.filter(v=>/^nl/i.test(v.lang)),score=v=>/natural|neural|online|premium/i.test(v.name)?10:0;return(nl.length?nl:voices).sort((a,b)=>score(b)-score(a))[0]||null}
