function safeResultUrl(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.toString():null}catch{return null}}
function showJarvisResult(j){const text=formatCommandResult(j),existing=$('#answer');if(existing&&!$('#layer').classList.contains('hidden')){existing.textContent=text;return}const layer=$('#layer'),body=$('#layerBody');layer.classList.remove('hidden');$('#layerSmall').textContent=`JARVIS · ${String(j.voice_mode||j.status||'RESULTAAT').toUpperCase()}`;$('#layerTitle').textContent='Gecontroleerd resultaat';body.replaceChildren();const grid=document.createElement('div');grid.className='grid';const result=document.createElement('div');result.className='card';result.style.gridColumn='1/-1';const heading=document.createElement('h3');heading.textContent='ANTWOORD EN UITVOERING';const answer=document.createElement('div');answer.className='answer';answer.style.whiteSpace='pre-wrap';answer.textContent=text;result.append(heading,answer);grid.append(result);const sources=[...(j.sources||[]),...(j.web?.sources||[])],unique=[...new Map(sources.filter(Boolean).map(x=>[x.url||`${x.source_id}:${x.method||''}`,x])).values()];if(unique.length){const sourceCard=document.createElement('div');sourceCard.className='card';sourceCard.style.gridColumn='1/-1';const h=document.createElement('h3');h.textContent='BRONNEN EN PROVENANCE';sourceCard.append(h);for(const source of unique.slice(0,12)){const row=document.createElement('p'),url=safeResultUrl(source.url),label=source.title||source.source_name||source.source_id||url||'Onbekende bron';if(url){const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=label;row.append(link)}else row.append(document.createTextNode(label));row.append(document.createTextNode(` · ${source.source_kind||'onbekend'} · ${source.provider_verified?'provider geverifieerd':'brongebonden, niet provider-geverifieerd'}`));sourceCard.append(row)}grid.append(sourceCard)}body.append(grid)}
function cssEscape(value){return globalThis.CSS?.escape?CSS.escape(String(value)):String(value).replace(/[^A-Za-z0-9_-]/g,'')}
const UICommandBus={async dispatch(cmd,result){if(!cmd||!cmd.type)return;if(cmd.type==='OPEN_ENGINE'&&MODULES[cmd.target])await openModule(cmd.target);else if(cmd.type==='CLOSE_ENGINE'){$('#layer').classList.add('hidden');focus=null}else if(cmd.type==='OPEN_CONNECTOR'){await openModule('integraties');const card=document.querySelector(`[data-connector="${cssEscape(cmd.target)}"]`);card?.scrollIntoView({behavior:'smooth',block:'center'});card?.animate?.([{boxShadow:'0 0 0 rgba(255,157,61,0)'},{boxShadow:'0 0 30px rgba(255,157,61,.7)'},{boxShadow:'0 0 0 rgba(255,157,61,0)'}],{duration:1500})}else if(cmd.type==='FOCUS_NODE'&&MODULES[cmd.target])focusOn(cmd.target);else if(cmd.type==='CENTER_GRAPH'){focus=null;yaw=0;pitch=-.08;zoom=1}else if(['SHOW_RESULTS','SHOW_REPORT','SHOW_TASK','SHOW_VEHICLE'].includes(cmd.type))showJarvisResult(result);else if(cmd.type==='SCROLL_TO'){const target=document.querySelector(`[data-connector="${cssEscape(cmd.target||'')}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'})}else if(cmd.type==='SET_JARVIS_STATE'&&cmd.state==='STANDBY')setTimeout(()=>endJarvisConversation(false),600);else if(cmd.type==='SHOW_NOTIFICATION')toast(cmd.message||'Jarvis-melding')},async apply(commands,result){for(const cmd of commands)await this.dispatch(cmd,result)}};
async function route(raw,voice=false){const text=String(raw||'').trim();if(!text)return;$('#command').value='';try{const j=await executeJarvisTurn(text);if(voice&&JARVIS.fallback)fallbackSpeak(j.answer);else if(JARVIS.realtimeConnected)requestRealtimeSpeech(j.answer,j.voice_mode);return j}catch(e){setJarvisState('ERROR',e.message);if(voice&&JARVIS.fallback)fallbackSpeak(`De opdracht is niet uitgevoerd. ${e.message}`);throw e}}
$('#mic').onclick=activateJarvis;$('#send').onclick=()=>route($('#command').value,false).catch(()=>{});$('#command').addEventListener('keydown',e=>{if(e.key==='Enter')route($('#command').value,false).catch(()=>{})});if(speechSynthesis)speechSynthesis.onvoiceschanged=()=>fallbackVoice();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&JARVIS.enabled&&!JARVIS.realtimeConnected)startWakeListener()});fetch('/api/jarvis/status').then(r=>r.ok?r.json():null).then(s=>{if(s?.conversation_timeout_ms)JARVIS.timeoutMs=s.conversation_timeout_ms;if(!s?.realtime_configured)$('#listenText').textContent='Klik eenmaal · Realtime niet geconfigureerd, fallback beschikbaar'}).catch(()=>{});
async function loadSystemStatus(){try{const [hr,cr,jr]=await Promise.all([fetch('/api/health'),fetch('/api/connectors'),fetch('/api/jarvis/status')]);if(!hr.ok||!cr.ok||!jr.ok)throw new Error('Statusroute niet beschikbaar');const h=await hr.json(),c=await cr.json(),j=await jr.json();window.__foundlyConnectorStatus={connected:Number(c.connected||0),configured:Number(c.configured||0),total:Number(c.total||h.total_connectors||93),connectors:c.connectors||[],google:c.google||{},openai_search:c.openai_search||{configured:Boolean(h.openai_search_configured)}};if($('#coreState'))$('#coreState').textContent=j.core_available?'PASS':'FOUT';if($('#runtimeState'))$('#runtimeState').textContent=j.worker?.status||'ONBEKEND';if($('#memoryState'))$('#memoryState').textContent=j.memory?.durable?'PERSISTENT':(j.memory?.persisted?'LOKALE CACHE':'NIET BEWEZEN');if($('#connectorState'))$('#connectorState').textContent=`${window.__foundlyConnectorStatus.connected}/${window.__foundlyConnectorStatus.total}`;}catch{window.__foundlyConnectorStatus={connected:0,configured:0,total:93,connectors:[]};if($('#coreState'))$('#coreState').textContent='FOUT';if($('#runtimeState'))$('#runtimeState').textContent='ONBEKEND';if($('#memoryState'))$('#memoryState').textContent='ONBEKEND';if($('#connectorState'))$('#connectorState').textContent='?/93';}}loadSystemStatus();setInterval(loadSystemStatus,30000);
(function oauthFeedback(){const p=new URLSearchParams(location.search),boot=Number(p.get('bootstrap')||0);for(const id of ['google','meta','linkedin','tiktok','wix']){if(p.get(id)==='connected')setTimeout(async()=>{toast(`${id.toUpperCase()} gekoppeld${boot?' · '+boot+' records ingeladen':''}`);await loadSystemStatus();if(p.get('open')==='integraties')await renderIntegrations();refreshEvents()},300);if(p.get(id)==='error')setTimeout(()=>toast(`${id.toUpperCase()} koppeling fout: ${p.get('message')||'onbekend'}`),300)}if(p.has('open'))setTimeout(()=>openModule(p.get('open')),150);if([...p.keys()].some(k=>['google','meta','linkedin','tiktok','wix','message','bootstrap'].includes(k)))setTimeout(()=>history.replaceState({},'',location.pathname+(p.get('open')?'?open='+encodeURIComponent(p.get('open')):'')),1200)})();
const __qs=new URLSearchParams(location.search);if(__qs.get('open')==='integraties'){setTimeout(()=>openModule('integraties'),250)}
// Real operating-system event stream. No simulated/fake activity is shown.
async function refreshEvents(){try{const r=await fetch('/api/events'),j=await r.json();if(!r.ok)return;const box=$('#events');if(!box)return;box.innerHTML='';for(const ev of (j.events||[]).slice(0,8)){const d=document.createElement('div');d.className='ev';const at=ev.at?new Date(ev.at).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'}):'--:--';d.textContent=`${at} · ${ev.message}`;box.appendChild(d)}}catch{}}
refreshEvents();setInterval(refreshEvents,10000);
